{"command":"python3 << 'PY'
import workcell
from PIL import Image

def blobs(path):
    im = Image.open(path)
    w,h = im.size
    pix = im.load()
    mask=[[False]*w for _ in range(h)]
    for y in range(h):
        for x in range(w):
            r,g,b=pix[x,y]
            br=(r+g+b)/3
            mask[y][x]= 15< br <90
    visited=[[False]*w for _ in range(h)]
    out=[]
    for y in range(h):
        for x in range(w):
            if not mask[y][x] or visited[y][x]:
                continue
            stack=[(x,y)]; visited[y][x]=True; pts=[]
            while stack:
                cx,cy=stack.pop(); pts.append((cx,cy))
                for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    nx,ny=cx+dx,cy+dy
                    if 0<=nx<w and 0<=ny<h and mask[ny][nx] and not visited[ny][nx]:
                        visited[ny][nx]=True; stack.append((nx,ny))
            if 30<len(pts)<2000:
                xs=[p[0] for p in pts]; ys=[p[1] for p in pts]
                out.append((len(pts), round(sum(xs)/len(xs),1), round(sum(ys)/len(ys),1)))
    return out

base_x, base_y = 383.681, 263.882
for z in (80, 90):
    r = workcell.robot("move", f"{base_x:.3f}", f"{base_y:.3f}", str(z))
    c = workcell.robot("camera", "wrist")
    path = c.text.split()[-1]
    print(z, path, blobs(path), r.text)
print(workcell.robot("status").text)
